import React, { useState, useEffect, useRef } from 'react';
import MeshSphere from '../components/MeshSphere';

const PHASES = [
  { name:'Andas in',  seconds:4, label:'Djupt in', hue1:195, hue2:215, speed:0.22, distort:0.1 },
  { name:'Håll',      seconds:7, label:'Stilla',   hue1:210, hue2:228, speed:0.08, distort:0.05 },
  { name:'Andas ut',  seconds:8, label:'Ut sakta', hue1:180, hue2:200, speed:0.20, distort:0.1 },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(()=>{ c--; setCount(c); if(c<=0){clearInterval(timer.current);const np=(pi+1)%3;setTimeout(()=>runPhase(np,np===0?ci+1:ci),350);}},1000);
  };
  const start = ()=>{ setRunning(true); setDone(false); runPhase(0,0); };
  useEffect(()=>()=>clearInterval(timer.current),[]);
  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, display:'flex', flexDirection:'column', position:'relative', overflow:'hidden' }}>
      <div style={{ padding:'22px 22px 0' }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Andning · Klart</span>
      </div>
      <div style={{ flex:1, display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'0 20px' }}>
        <div style={{ fontSize:'clamp(52px,14vw,86px)', fontWeight:900, letterSpacing:'-0.055em', lineHeight:0.84, color:'#111010', textTransform:'uppercase', marginBottom:'-24px', position:'relative', zIndex:3 }}>
          BRA
        </div>
        <div style={{ position:'relative', zIndex:2 }}>
          <MeshSphere size={220} speed={0.65} distort={0.1} hue1={160} hue2={180} />
        </div>
        <div style={{ position:'relative', zIndex:3, marginTop:'-10px' }}>
          <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:14 }} />
          <p style={{ fontSize:14, color:'rgba(17,16,16,0.42)', marginBottom:20, fontWeight:300 }}>4 omgångar klara. Ditt nervsystem har lugnat ner sig.</p>
          <div style={{ display:'flex', gap:8 }}>
            <button onClick={()=>setPage('checkin')} style={{ flex:1, padding:'13px', borderRadius:100, background:'#111010', color:'#f0ede8', fontSize:13, fontWeight:600, border:'none' }}>Check-in →</button>
            <button onClick={()=>{setDone(false);setRunning(false);}} style={{ padding:'13px 18px', borderRadius:100, background:'rgba(17,16,16,0.06)', border:'1px solid rgba(17,16,16,0.1)', color:'rgba(17,16,16,0.5)', fontSize:13 }}>Igen</button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, display:'flex', flexDirection:'column', overflow:'hidden', position:'relative' }}>

      {/* Rotated label */}
      <div style={{ position:'fixed', left:16, top:'50%', transform:'translateY(-50%) rotate(-90deg)', zIndex:10, pointerEvents:'none' }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(17,16,16,0.18)' }}>Spiral</span>
      </div>

      {/* Phase indicators — centered */}
      <div style={{ textAlign:'center', padding:'24px 22px 0', position:'relative', zIndex:3 }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.28)', marginBottom:16 }}>4 – 7 – 8</p>
        <div style={{ display:'flex', gap:20, justifyContent:'center' }}>
          {PHASES.map((p, i) => (
            <div key={i} style={{ textAlign:'center' }}>
              <div style={{ fontSize:22, fontWeight:900, letterSpacing:'-0.04em', lineHeight:1, color:running&&phase===i?'#111010':'rgba(17,16,16,0.2)', transition:'color .5s' }}>{p.seconds}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, textTransform:'uppercase', letterSpacing:'0.1em', color:running&&phase===i?'rgba(17,16,16,0.5)':'rgba(17,16,16,0.18)', transition:'color .5s', marginTop:3 }}>{p.name}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Orb */}
      <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center' }}>
        <div style={{ position:'relative',
          transition: running ? phase===0?`transform ${PHASES[0].seconds}s linear`:phase===1?'transform .8s ease-out':`transform ${PHASES[2].seconds}s linear` : 'transform 1.4s cubic-bezier(0.16,1,0.3,1)',
          transform: running?(phase<=1?'scale(1.28)':'scale(0.80)'):'scale(1)',
        }}>
          <MeshSphere size={300} speed={running?cur.speed:0.32} distort={running?cur.distort:0.38} hue1={running?cur.hue1:195} hue2={running?cur.hue2:212} />
          {running && (
            <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(17,16,16,0.45)', marginBottom:4 }}>{cur.name}</div>
              <div style={{ fontSize:58, fontWeight:900, color:'rgba(17,16,16,0.75)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(17,16,16,0.28)', marginTop:5 }}>{cycle+1} / {TOTAL}</div>
            </div>
          )}
        </div>
      </div>

      {/* Bottom */}
      <div style={{ padding:'0 22px 16px', position:'relative', zIndex:3 }}>
        {running ? (
          <div style={{ background:'rgba(17,16,16,0.05)', border:'1px solid rgba(17,16,16,0.08)', borderRadius:14, padding:'12px 16px', textAlign:'center' }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.12em', textTransform:'uppercase', color:'rgba(17,16,16,0.4)' }}>{cur.label}</p>
          </div>
        ) : (
          <>
            <div style={{ fontSize:'clamp(32px,8vw,50px)', fontWeight:900, letterSpacing:'-0.05em', lineHeight:0.88, color:'#111010', textTransform:'uppercase', marginBottom:10 }}>
              ANDNING
            </div>
            <p style={{ fontSize:13, color:'rgba(17,16,16,0.42)', fontWeight:300, lineHeight:1.75, marginBottom:20 }}>
              Aktiverar det parasympatiska nervsystemet. 4 minuter.
            </p>
            <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'#111010', color:'#f0ede8', fontSize:13, fontWeight:700, border:'none', boxShadow:'0 4px 16px rgba(0,0,0,0.12)' }}>
              Starta →
            </button>
          </>
        )}
      </div>
    </div>
  );
}
